head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > caseSensitive]<br/>입력값으로 아이템을 검색할 때 영문 대소문자를 구분할지 설정합니다.",
    "validation" : [
        "true 설정 시, 아이템을 검색할때 영문 대소문자를 구분하여 검색합니다.",
        "미설정 시, 아이템을 검색할때 영문 대소문자를 구분하여 검색합니다.",
        "false 설정 시, 아이템을 검색할때 영문 대소문자를 구분하지 않고 검색합니다.",
        "false 설정 시, 편집 완료 시 사용자의 입력값과 대소문자까지 일치하는 아이템을 먼저 선택합니다.",
        "false 설정 시, 대소문자까지 일치하는 아이템이 없으면 대소문자를 구분하지 않고 일치하는 아이템을 선택합니다.",
        "편집 완료 시 사용자의 입력값과 일치하는 아이템을 찾아 선택할 때도 적용됩니다.",
        "useKeywordHighlight='true' 이면 아이템 리스트창에서 검색어를 강조할때도 적용됩니다.",
    ]
}

// 아이템
//  - Mb / MB : Label 의 철자가 같고 대소문자만 다른 쌍 (Value 는 서로 다름, 소문자가 섞인 Mb 가 앞 순서)
//  - Gb : 대소문자만 다른 짝이 없는 아이템
//  - ms : 초기 선택 아이템 (일치하는 아이템을 찾지 못하면 이 아이템이 그대로 남는다)
scwin.arrUnit = [
    { "label" : "ms", "value" : "millisecond" },
    { "label" : "Mb", "value" : "megabit" },
    { "label" : "MB", "value" : "megabyte" },
    { "label" : "Gb", "value" : "gigabit" }
];

// 사용자가 입력한 값, 검색 결과 확인 버튼을 누르는 시점의 리스트창 아이템과 강조된 부분
scwin.gVar = { "typedValue" : "", "arrItem" : [], "arrKeyword" : [] };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 아이템 DataList 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_unit">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_unit.setJSON(scwin.arrUnit);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (3 = false, 2 = true)
    con_caseSensitive.setValue("3");
    con_useKeywordHighlight.setValue("2");

    // 검색 결과 확인 버튼 클릭 시 목록이 먼저 닫히므로 mousedown capture 단계에서 리스트창 상태를 기록
    btn_getSearchInfo.render.addEventListener("mousedown", scwin.captureListState, true);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 아이템(Label / Value) : ms / millisecond, Mb / megabit, MB / megabyte, Gb / gigabit (초기 선택 : ms)\n[절차]\n1. 결과창 clear -> 대상 클릭 -> m 또는 M 입력 -> 리스트창이 열린 상태에서 검색 결과 확인\n2. 결과창 clear -> 대상 클릭 -> MB, mb, gb 중 하나 입력 -> 선택 아이템 확인 (버튼을 누르면 포커스가 해제되어 편집이 끝난다)"', '', 'label1');

    scwin.gVar.typedValue = "";

    // gdl_boolean 은 getText 로 읽는다 (미설정은 createCList 가 속성에서 제외)
    let properties = {
        caseSensitive : con_caseSensitive.getText(),
        useKeywordHighlight : con_useKeywordHighlight.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_unit">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());

    // 편집이 끝나면 입력창의 표시값이 선택된 아이템으로 바뀌므로 사용자가 입력한 값을 따로 기록
    document.querySelector("input[id='" + target1.id + "_input']").addEventListener("input", function (e) {
        scwin.gVar.typedValue = e.target.value;
    });
};



// 버튼 mousedown 시점(목록이 닫히기 전)의 리스트창 표시 아이템과 강조된 부분 기록
scwin.captureListState = function (e) {
    scwin.gVar.arrItem = [];
    scwin.gVar.arrKeyword = [];

    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!itemTableElem) {
        return;
    }
    let objStyle = getComputedStyle(itemTableElem);
    if (objStyle.display === "none" || objStyle.visibility === "hidden") {
        return;
    }

    // 숨겨진 Row 는 제외하고 화면에 보이는 아이템만 수집
    let rowList = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr");
    for (let i = 0; i < rowList.length; i++) {
        if (rowList[i].offsetHeight > 0) {
            scwin.gVar.arrItem.push(rowList[i].textContent.trim());
            let keywordList = rowList[i].querySelectorAll(".w2autoComplete_keyword");
            for (let j = 0; j < keywordList.length; j++) {
                scwin.gVar.arrKeyword.push(keywordList[j].textContent);
            }
        }
    }
};



// 입력값으로 검색된 아이템, 리스트창에서 강조된 부분 출력 (validation 1, 2, 3, 7)
scwin.btn_getSearchInfo_onclick = function (e) {
    let strItem = scwin.gVar.arrItem.length > 0 ? scwin.gVar.arrItem.join(", ") : "없음";
    let strKeyword = scwin.gVar.arrKeyword.length > 0 ? scwin.gVar.arrKeyword.join(", ") : "없음";
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 : " + scwin.gVar.typedValue + " -> 검색된 아이템 : " + strItem + " -> 강조된 부분 : " + strKeyword);
};



// 편집 완료 후 선택된 아이템 출력 (validation 4, 5, 6)
scwin.btn_getSelectedInfo_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 : " + scwin.gVar.typedValue + " -> 선택된 아이템(Label / Value) : " + target1.getText() + " / " + target1.getValue());
};
